using System.Text;

// CA1305: the emitters only interpolate integers and strings, and Generator.Render runs under the invariant culture.
#pragma warning disable CA1305

namespace MikePDF.ProtocolGen;

/// <summary>Emits the C# half: enums, plain payload classes with Validate(), a strict Read() and a Write(), and the type switches. No MessagePackSerializer, no MessagePackObject.</summary>
internal static class CSharpEmitter
{
    private const string Header =
        "// <auto-generated>\n" +
        "// Generated by tools/MikePDF.ProtocolGen from src/MikePDF.Protocol/schema/mikepdf.protocol.json. Do not edit.\n" +
        "// </auto-generated>\n" +
        "#nullable enable\n\n";

    public static IEnumerable<(string Path, string Content)> Emit(Schema s)
    {
        yield return ("src/MikePDF.Protocol/generated/Enums.g.cs", Enums(s));
        yield return ("src/MikePDF.Protocol/generated/Messages.g.cs", Messages(s));
        yield return ("src/MikePDF.Protocol/generated/Dispatch.g.cs", Dispatch(s));
    }

    private static string Enums(Schema s)
    {
        var b = new StringBuilder(Header);
        b.Append("using MessagePack;\n\nnamespace MikePDF.Protocol;\n\n");
        b.Append("/// <summary>Constants taken from the schema.</summary>\n");
        b.Append("public static class ProtocolInfo\n{\n");
        b.Append($"    public const uint SchemaVersion = {s.SchemaVersion}u;\n");
        b.Append($"    public const int MaxFrameBytes = {s.MaxFrameBytes};\n");
        b.Append($"    public const uint MaxDeadlineMs = {s.MaxDeadlineMs}u;\n");
        b.Append("}\n\n");

        foreach (var e in s.Enums)
        {
            b.Append($"public enum {e.Name} : ushort\n{{\n");
            foreach (var v in e.Values) b.Append($"    {v.Name} = {v.Value},\n");
            b.Append("}\n\n");
            b.Append($"public static class {e.Name}Info\n{{\n");
            b.Append($"    public static bool IsDefined({e.Name} value) => value switch\n    {{\n");
            b.Append("        " + string.Join(" or ", e.Values.Select(v => $"{e.Name}.{v.Name}")) + " => true,\n");
            b.Append("        _ => false,\n    };\n\n");
            b.Append("    /// <summary>Strict decoder: an integer that fits u16 and names a defined value.</summary>\n");
            b.Append($"    internal static {e.Name} Read(ref MessagePackReader reader)\n    {{\n");
            b.Append($"        var value = ({e.Name})StrictReader.ReadU16(ref reader, 0, ushort.MaxValue);\n");
            b.Append($"        return IsDefined(value) ? value : throw StrictReader.Limit(\"Undefined {e.Name} value.\");\n    }}\n");
            if (e.Name == "Status")
            {
                var payload = e.Values.Where(v => v.CarriesPayload).Select(v => $"Status.{v.Name}");
                b.Append("\n    /// <summary>True for statuses whose response carries a reply payload; all others carry nil.</summary>\n");
                b.Append($"    public static bool CarriesPayload(Status value) => value is {string.Join(" or ", payload)};\n");
            }

            b.Append("}\n\n");
        }

        b.Append("/// <summary>Wire id of a request/reply pair. The reply carries the id of the request it answers.</summary>\n");
        b.Append("public enum MessageType : ushort\n{\n");
        foreach (var m in s.Messages) b.Append($"    {m.Name} = {m.Id},\n");
        b.Append("}\n\n");
        b.Append("public enum DocumentIdRule\n{\n    /// <summary>The header documentId must be 0.</summary>\n    None,\n\n    /// <summary>The header documentId must be a document handle (non-zero).</summary>\n    Required,\n}\n\n");
        b.Append("public static class MessageTypeInfo\n{\n");
        b.Append("    public static bool IsDefined(MessageType value) => value switch\n    {\n");
        b.Append("        " + string.Join(" or ", s.Messages.Select(m => $"MessageType.{m.Name}")) + " => true,\n");
        b.Append("        _ => false,\n    };\n\n");
        b.Append("    public static DocumentIdRule DocumentRule(MessageType value) => value switch\n    {\n");
        foreach (var m in s.Messages) b.Append($"        MessageType.{m.Name} => DocumentIdRule.{m.DocumentId},\n");
        b.Append("        _ => throw new ArgumentOutOfRangeException(nameof(value)),\n    };\n");
        b.Append("}\n");
        return b.ToString();
    }

    private static string Messages(Schema s)
    {
        var b = new StringBuilder(Header);
        b.Append("using MessagePack;\n\nnamespace MikePDF.Protocol;\n");
        foreach (var m in s.Messages)
        {
            Struct(b, m, m.Request, "IRequestMessage", "request");
            Struct(b, m, m.Reply, "IReplyMessage", "reply");
        }

        return b.ToString();
    }

    private static string ClrType(FieldType t, FieldDef f) => t switch
    {
        FieldType.U16 => "ushort",
        FieldType.U32 => "uint",
        FieldType.U64 => "ulong",
        FieldType.I32 => "int",
        FieldType.F32 => "float",
        FieldType.Bool => "bool",
        FieldType.Text => "string",
        FieldType.Enum => f.EnumName!,
        _ => throw new InvalidOperationException(t.ToString()),
    };

    private static void Struct(StringBuilder b, MessageDef m, StructDef st, string iface, string role)
    {
        b.Append($"\n/// <summary>The {role} payload of {m.Name} (message type {m.Id}).</summary>\n");
        b.Append($"public sealed class {st.TypeName} : {iface}\n{{\n");
        foreach (var f in st.Fields)
        {
            if (f.Doc is not null) b.Append($"    /// <summary>{f.Doc}</summary>\n");
            var (type, init) = f.Type switch
            {
                FieldType.Array => (ClrType(f.Element!.Value, f) + "[]", " = [];"),
                FieldType.Text when f.Optional => ("string?", ""),
                FieldType.Text => ("string", " = \"\";"),
                _ => (ClrType(f.Type, f), ""),
            };
            b.Append($"    public {type} {Schema.Pascal(f.Name)} {{ get; set; }}{init}\n");
        }

        if (st.Fields.Count > 0) b.Append('\n');
        b.Append($"    public MessageType MessageType => MessageType.{m.Name};\n\n");

        // Strict decoder. Mirrors the C++ decode() line for line.
        b.Append("    /// <summary>\n    /// The only decoder for this type. Reads exactly the declared fields, enforcing wire types and every limit as it goes;\n");
        b.Append("    /// there is no other decoder (see StrictReader).\n    /// </summary>\n");
        b.Append($"    internal static {st.TypeName} Read(ref MessagePackReader reader)\n    {{\n");
        b.Append($"        StrictReader.ExpectArray(ref reader, {st.Fields.Count});\n");
        b.Append($"        var message = new {st.TypeName}();\n");
        foreach (var f in st.Fields)
        {
            var p = Schema.Pascal(f.Name);
            if (f.Type == FieldType.Array)
            {
                var element = f.Element!.Value;
                b.Append($"        var {f.Name}Count = StrictReader.ReadArrayHeader(ref reader, {f.MaxCount});\n");
                b.Append($"        var {f.Name} = new {ClrType(element, f)}[{f.Name}Count];\n");
                b.Append($"        for (var i = 0; i < {f.Name}.Length; i++)\n        {{\n            {f.Name}[i] = {ReadCall(element, f)};\n        }}\n\n");
                b.Append($"        message.{p} = {f.Name};\n");
            }
            else
            {
                b.Append($"        message.{p} = {ReadCall(f.Type, f)};\n");
            }
        }

        b.Append("        return message;\n    }\n\n");

        // Encoder. Does not validate: ProtocolCodec calls Validate() first. Always writes the shortest MessagePack form.
        b.Append("    /// <summary>Writes the payload array. Does not validate; the codec validates before it writes.</summary>\n");
        b.Append("    public void Write(ref MessagePackWriter writer)\n    {\n");
        b.Append($"        writer.WriteArrayHeader({st.Fields.Count});\n");
        foreach (var f in st.Fields)
        {
            var p = Schema.Pascal(f.Name);
            if (f.Type == FieldType.Array)
                b.Append($"        writer.WriteArrayHeader({p}.Length);\n        foreach (var v in {p})\n        {{\n            {WriteCall(f.Element!.Value, "v")}\n        }}\n\n");
            else
                b.Append($"        {WriteCall(f.Type, p)}\n");
        }

        b.Append("    }\n\n");

        b.Append("    /// <summary>Checks every schema limit. Returns null when the message is valid.</summary>\n");
        b.Append("    public ProtocolFailure? Validate()\n    {\n");

        foreach (var f in st.Fields)
        {
            var p = Schema.Pascal(f.Name);
            var w = $"{st.TypeName}.{f.Name}";
            if (f.Type == FieldType.Array)
            {
                b.Append($"        if ({p} is null || {p}.Length > {f.MaxCount}) return ProtocolFailure.Invalid(\"{w} is null or has more than {f.MaxCount} elements\");\n");
                var cond = Condition(f.Element!.Value, f, $"{p}[i]");
                if (cond is not null)
                {
                    b.Append($"        for (var i = 0; i < {p}.Length; i++)\n");
                    b.Append($"        {{\n            if ({cond}) return ProtocolFailure.Invalid(\"{w}[\" + i + \"] violates its limit\");\n        }}\n\n");
                }
            }
            else
            {
                var cond = Condition(f.Type, f, p);
                if (cond is not null) b.Append($"        if ({cond}) return ProtocolFailure.Invalid(\"{w} violates its limit\");\n");
            }
        }

        foreach (var f in st.Fields.Where(f => f.SameLengthAs is not null))
        {
            var p = Schema.Pascal(f.Name);
            var o = Schema.Pascal(f.SameLengthAs!);
            b.Append($"        if ({p}.Length != {o}.Length) return ProtocolFailure.Invalid(\"{st.TypeName}.{f.Name} must have as many elements as {f.SameLengthAs}\");\n");
        }

        b.Append("        return null;\n    }\n}\n");
    }

    private static string Lit(FieldType t, decimal v) => t switch
    {
        FieldType.U32 => Schema.Inv(v) + "u",
        FieldType.U64 => Schema.Inv(v) + "UL",
        FieldType.F32 => FloatLit(v) + "f",
        _ => Schema.Inv(v),
    };

    private static string Bound(FieldType t, FieldDef f, bool upper)
    {
        var v = upper ? f.Max : f.Min ?? f.ExclusiveMin;
        if (v is not null) return Lit(t, v.Value);
        return t switch
        {
            FieldType.I32 => upper ? "int.MaxValue" : "int.MinValue",
            FieldType.U16 => upper ? "ushort.MaxValue" : "0",
            FieldType.U32 => upper ? "uint.MaxValue" : "0u",
            FieldType.U64 => upper ? "ulong.MaxValue" : "0UL",
            _ => throw new InvalidOperationException(t.ToString()),
        };
    }

    private static string ReadCall(FieldType t, FieldDef f) => t switch
    {
        FieldType.U16 => $"StrictReader.ReadU16(ref reader, {Bound(t, f, false)}, {Bound(t, f, true)})",
        FieldType.U32 => $"StrictReader.ReadU32(ref reader, {Bound(t, f, false)}, {Bound(t, f, true)})",
        FieldType.U64 => $"StrictReader.ReadU64(ref reader, {Bound(t, f, false)}, {Bound(t, f, true)})",
        FieldType.I32 => $"StrictReader.ReadI32(ref reader, {Bound(t, f, false)}, {Bound(t, f, true)})",
        FieldType.F32 => $"StrictReader.ReadF32(ref reader, {Bound(t, f, false)}, {Bound(t, f, true)}, {(f.ExclusiveMin is not null ? "true" : "false")})",
        FieldType.Bool => "StrictReader.ReadBool(ref reader)",
        FieldType.Text when f.Optional => $"StrictReader.ReadOptionalString(ref reader, {f.MaxBytes})",
        FieldType.Text => $"StrictReader.ReadString(ref reader, {f.MaxBytes})",
        FieldType.Enum => $"{f.EnumName}Info.Read(ref reader)",
        _ => throw new InvalidOperationException(t.ToString()),
    };

    private static string WriteCall(FieldType t, string x) => t switch
    {
        FieldType.Enum => $"writer.Write((ushort){x});",
        _ => $"writer.Write({x});",
    };

    // The failing condition for one value of scalar type t, or null when the type itself is the only limit.
    private static string? Condition(FieldType t, FieldDef f, string x)
    {
        switch (t)
        {
            case FieldType.Bool:
                return null;
            case FieldType.Enum:
                return $"!{f.EnumName}Info.IsDefined({x})";
            case FieldType.Text:
                return f.Optional ? $"{x} is not null && !ProtocolText.IsValid({x}, {f.MaxBytes})" : $"!ProtocolText.IsValid({x}, {f.MaxBytes})";
            case FieldType.F32:
                var parts = new List<string> { $"!float.IsFinite({x})" };
                if (f.Min is not null) parts.Add($"{x} < {Lit(t, f.Min.Value)}");
                if (f.ExclusiveMin is not null) parts.Add($"{x} <= {Lit(t, f.ExclusiveMin.Value)}");
                parts.Add($"{x} > {Lit(t, f.Max!.Value)}");
                return string.Join(" || ", parts);
            default:
                var (lo, hi) = Schema.Range(t);
                var ints = new List<string>();
                if (f.Min is not null && f.Min > lo) ints.Add($"{x} < {Lit(t, f.Min.Value)}");
                if (f.Max is not null && f.Max < hi) ints.Add($"{x} > {Lit(t, f.Max.Value)}");
                return ints.Count == 0 ? null : string.Join(" || ", ints);
        }
    }

    internal static string FloatLit(decimal v)
    {
        var s = Schema.Inv(v);
        return s.Contains('.') ? s : s + ".0";
    }

    private static string Dispatch(Schema s)
    {
        var b = new StringBuilder(Header);
        b.Append("using MessagePack;\n\nnamespace MikePDF.Protocol;\n\n");
        b.Append("/// <summary>Type switches over the closed message set. No reflection and no polymorphic deserialisation.</summary>\n");
        b.Append("internal static class ProtocolDispatch\n{\n");
        foreach (var (role, iface, pick) in new (string, string, Func<MessageDef, StructDef>)[]
        {
            ("Request", "IRequestMessage", m => m.Request),
            ("Reply", "IReplyMessage", m => m.Reply),
        })
        {
            b.Append($"    public static {iface} Read{role}(MessageType type, ref MessagePackReader reader) => type switch\n    {{\n");
            foreach (var m in s.Messages) b.Append($"        MessageType.{m.Name} => {pick(m).TypeName}.Read(ref reader),\n");
            b.Append("        _ => throw new ArgumentOutOfRangeException(nameof(type)),\n    };\n\n");

            b.Append($"    public static void Write{role}({iface} message, ref MessagePackWriter writer)\n    {{\n        switch (message)\n        {{\n");
            foreach (var m in s.Messages)
            {
                var t = pick(m).TypeName;
                b.Append($"            case {t} m:\n                m.Write(ref writer);\n                break;\n");
            }

            b.Append("            default:\n                throw new ArgumentException(\"Unknown payload type\", nameof(message));\n        }\n    }\n");
            if (role == "Request") b.Append('\n');
        }

        b.Append("}\n");
        return b.ToString();
    }
}
